import {icons,iconHTML,escapeHTML as esc} from './service-visuals.mjs';
// Teaching schematics: arrows show the named relationship, not every deployment detail.
export const stories=[
{id:'serverless',title:'A request becomes a response.',subtitle:'Serverless API',question:'A mobile app needs an API without managing application servers.',nodes:[['api-gateway','API Gateway','Receive the request'],['lambda','Lambda','Run the application'],['dynamodb','DynamoDB','Read or write data']],edges:[[0,1,'invoke'],[1,2,'SDK request']],steps:[['A controlled front door','API Gateway menerima HTTP request. Configure authentication, routes, throttling and the Lambda integration for your API.'],['Compute when invoked','Lambda menjalankan business logic. Its execution role needs permission to call DynamoDB; the API caller and function role are different identities.'],['A persistent data layer','DynamoDB menyimpan data using keys and access patterns. The function returns a response through API Gateway. Arrows show the request path; the return path is omitted.']],trap:'Serverless does not remove responsibility for authorization, idempotency or data modelling.',source:'https://docs.aws.amazon.com/apigateway/latest/developerguide/http-api-dynamo-db.html'},
{id:'edge',title:'Cache near people. Compute at the origin.',subtitle:'Web delivery',question:'Serve a dynamic web application while reducing repeated origin requests.',nodes:[['cloudfront','CloudFront','Edge cache'],['application-load-balancer-alb','ALB','Application routing'],['ec2','EC2 targets','Application compute'],['rds','RDS','Relational data']],edges:[[0,1,'cache miss / dynamic'],[1,2,'route request'],[2,3,'database query']],steps:[['Start at the edge','CloudFront can answer a cache hit without forwarding that request to the origin. Cache behaviour and keys determine what is reusable.'],['Route at the origin','For this example, an Application Load Balancer is the CloudFront origin. It routes requests to healthy application targets.'],['Run the application','EC2 targets process application logic. EC2 Auto Scaling can adjust capacity; the load balancer itself does not add instances.'],['Read durable state','The application queries RDS. Protect the database network path and credentials. This schematic omits subnets, multi-AZ deployment and return traffic.']],trap:'Personalized or sensitive responses need appropriate cache policies. Do not cache every response indiscriminately.',source:'https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/DownloadDistS3AndCustomOrigins.html'},
{id:'fanout',title:'One event. Independent consumers.',subtitle:'Messaging & decoupling',question:'An order event must reach billing and fulfilment independently.',nodes:[['sns','SNS topic','Publish the event'],['sqs','Billing queue','Buffer separately'],['sqs','Fulfilment queue','Buffer separately'],['lambda','Billing worker','Process + acknowledge'],['lambda','Fulfilment worker','Process + acknowledge']],edges:[[0,1,'subscription'],[0,2,'subscription'],[1,3,'poll / invoke'],[2,4,'poll / invoke']],steps:[['Publish once','SNS fan-out delivers notifications to subscribed queues. Each queue needs appropriate access permissions.'],['Give billing its own buffer','The billing queue holds its own copy. A slow billing worker does not consume messages from the fulfilment queue.'],['Isolate fulfilment','The fulfilment subscription receives its own copy. In contrast, two consumers on ONE SQS queue compete for work; each does not automatically get a copy.'],['Process billing safely','A Lambda event source mapping polls the queue and invokes the function. Design for retries and duplicate processing; handle partial batch failures where appropriate.'],['Process fulfilment independently','The fulfilment worker handles its own backlog. Configure visibility timeout, redrive policies and monitoring for each consumer.']],trap:'Fan-out and load-sharing solve different problems. SNS plus separate queues creates independent delivery paths.',source:'https://docs.aws.amazon.com/sns/latest/dg/sns-sqs-as-subscriber.html'},
{id:'storage',title:'A disk, a shared folder, or an object?',subtitle:'Storage mental models',question:'Choose by access model before comparing capacity or price.',nodes:[['ebs','EBS','Block storage'],['efs','EFS','Shared file system'],['s3','S3','Object storage']],edges:[],steps:[['Think attached disk','EBS supplies block storage for EC2. The operating system can put a file system on the volume. Availability Zone placement and supported attachment modes matter.'],['Think shared file system','EFS supplies a managed NFS file system. Multiple supported clients can use shared files; security, mount targets and network access still matter.'],['Think object + key','S3 stores objects accessed through APIs. It is not a drop-in block disk or ordinary NFS mount. Applications must use an appropriate object access pattern.']],trap:'These are alternatives by access model, not an EBS → EFS → S3 pipeline. There is no universally “most powerful” storage service.',source:'https://aws.amazon.com/products/storage/'},
{id:'analytics',title:'Store the data. Describe it. Query it.',subtitle:'Data lake queries',question:'Query data in S3 without loading it into a dedicated warehouse first.',nodes:[['s3','S3','Data files'],['glue-data-catalog','Glue Data Catalog','Table metadata'],['athena','Athena','SQL engine']],edges:[[0,2,'read data'],[1,2,'table definitions']],steps:[['Objects hold the data','S3 contains data files. File format, partitioning and compression can affect query efficiency.'],['The catalog describes it','The Glue Data Catalog stores metadata such as schema and locations. It does not replace S3 as the storage location for those source files.'],['SQL connects both','Athena uses table definitions to query the data. The diagram shows data/metadata inputs, not a mandatory chronological pipeline. Permissions must allow the required access.']],trap:'The catalog stores metadata, not a second copy of all your source data.',source:'https://docs.aws.amazon.com/athena/latest/ug/data-sources-glue.html'},
{id:'operations',title:'Three questions. Three evidence trails.',subtitle:'Observability & audit',question:'You need to understand activity, performance and resource configuration.',nodes:[['cloudtrail','CloudTrail','Who did what?'],['cloudwatch','CloudWatch','How is it behaving?'],['aws-config','AWS Config','What changed in configuration?']],edges:[],steps:[['Audit activity','CloudTrail records supported account activity and API events. Event coverage depends on configuration; do not assume every data event is recorded by default.'],['Observe behaviour','CloudWatch brings metrics, logs and alarms into operational monitoring. The application must emit or integrate the telemetry you need.'],['Track configuration','AWS Config records supported resource configurations and evaluates rules. Recording scope and rule configuration determine what you see.']],trap:'These services complement each other. The visual is a comparison, not a traffic flow or a claim that one replaces the others.',source:'https://docs.aws.amazon.com/whitepapers/latest/aws-overview/management-governance.html'}
];
const positions=n=>n<=3?[[30,100],[280,100],[530,100]]:n===4?[[30,35],[530,35],[530,230],[30,230]]:[[280,15],[30,170],[530,170],[30,325],[530,325]];
export function diagramSVG(story,active){const pos=story.id==='analytics'?[[30,15],[530,15],[280,230]]:story.id==='serverless'?[[30,28],[530,28],[530,228]]:positions(story.nodes.length),height=Math.max(...pos.map(p=>p[1]))+140;return `<svg class="architecture-svg" viewBox="0 0 760 ${height}" role="img" aria-label="${esc(story.subtitle)} teaching diagram"><title>${esc(story.title)}</title><defs><marker id="arrow-tip" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 10 5 0 10z" fill="#54746b"/></marker></defs>${story.edges.map(([a,b,label])=>{const [ax,ay]=pos[a],[bx,by]=pos[b];let x1=ax+100,y1=ay+105,x2=bx+100,y2=by;if(ay===by){x1=ax+200;y1=ay+52;x2=bx;y2=by+52;if(ax>bx){x1=ax;x2=bx+200;}}const mx=(x1+x2)/2,my=(y1+y2)/2;return `<path d="M${x1} ${y1} L${x2} ${y2}" class="story-edge" marker-end="url(#arrow-tip)"/><rect x="${mx-78}" y="${my-12}" width="156" height="24" rx="6" fill="#f6f8f4"/><text x="${mx}" y="${my+4}" class="edge-label" text-anchor="middle">${esc(label)}</text>`;}).join('')}${story.nodes.map(([id,name,job],i)=>{const [x,y]=pos[i],src=icons[id]?.src;return `<g class="story-node ${i===active?'active':''}"><rect x="${x}" y="${y}" width="200" height="105" rx="16"/>${src?`<image href="${src}" x="${x+14}" y="${y+15}" width="36" height="36"/>`:''}<text x="${x+64}" y="${y+36}" class="node-name">${esc(name)}</text><text x="${x+15}" y="${y+76}" class="node-job">${esc(job)}</text></g>`;}).join('')}</svg>`;}
export function renderArchitecture(root,initial){let story=stories.find(s=>s.id===initial)||stories[0],step=0;root.innerHTML=`<div class="atlas-heading"><div><p class="section-context">ARCHITECTURE STORIES / FOLLOW THE MECHANISM</p><h1>See how the pieces fit.</h1><p class="lede">Klik satu langkah. Ikuti hubungan. Jelaskan alasan desainnya.</p></div><a class="button" href="#visuals">Browse service icons ↗</a></div><nav class="story-tabs" aria-label="Architecture stories">${stories.map(s=>`<button data-story="${s.id}" aria-pressed="${s.id===story.id}">${esc(s.subtitle)}</button>`).join('')}</nav><div id="story-workspace"></div>`;
 const draw=()=>{root.querySelectorAll('[data-story]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.story===story.id)));root.querySelector('#story-workspace').innerHTML=`<section class="story-board"><div class="story-title"><span class="section-context">${esc(story.subtitle)}</span><h2>${esc(story.title)}</h2><p>${esc(story.question)}</p></div><div class="diagram-scroller" tabindex="0" aria-label="Architecture diagram; scroll horizontally on small screens">${diagramSVG(story,step)}</div><p class="diagram-caption">${story.edges.length?'Arrows show the labelled relationship. Return paths and deployment details are simplified.':'Comparison view · these services are not connected in a pipeline.'}</p></section><div class="story-walkthrough"><nav class="story-step-list" aria-label="Choose an explanation step">${story.nodes.map(([id,name],i)=>`<button data-step="${i}" aria-pressed="${i===step}"><span>${i+1}</span>${iconHTML(id,28)}<b>${esc(name)}</b></button>`).join('')}</nav><article class="story-explanation" aria-live="polite"><span class="section-context">STEP ${step+1} / ${story.nodes.length}</span><h2>${esc(story.steps[step][0])}</h2><p>${esc(story.steps[step][1])}</p><div class="story-actions"><button data-move="-1" ${step===0?'disabled':''}>← Previous</button><button data-move="1" class="primary" ${step===story.nodes.length-1?'disabled':''}>Next step →</button></div><a href="#visuals/${story.nodes[step][0]}">Explore this service →</a></article></div><details class="story-trap"><summary>Check your understanding · What could go wrong?</summary><p>${esc(story.trap)}</p></details><p class="fine"><a href="${story.source}" target="_blank" rel="noopener">Read the AWS documentation ↗</a> · Teaching schematic, not a deployment template.</p>`;};
 root.onclick=e=>{const s=e.target.closest('[data-story]'),b=e.target.closest('[data-step]'),m=e.target.closest('[data-move]');if(s){story=stories.find(x=>x.id===s.dataset.story);step=0;history.replaceState(null,'','#architecture/'+story.id);draw();}if(b){step=Number(b.dataset.step);draw();root.querySelector(`[data-step="${step}"]`).focus({preventScroll:true});}if(m){step=Math.min(story.nodes.length-1,Math.max(0,step+Number(m.dataset.move)));draw();root.querySelector(`[data-move="${m.dataset.move}"]`)?.focus({preventScroll:true});}};draw();
}
